static long cal(int index, int consecutivePairs, int lastChar, String S, long[] cost) {
    if (index == S.length()) {
        return consecutivePairs == 1 ? 0 : Long.MAX_VALUE;
    }
    if (dp[index][consecutivePairs][lastChar] != -1) {
        return dp[index][consecutivePairs][lastChar];
    }
    int cur = S.charAt(index) - '0';
    long res = cal(index + 1, consecutivePairs + (cur == lastChar ? 1 : 0), cur, S, cost);
    if (res != Long.MAX_VALUE) {
        res += (cur == lastChar ? 0 : cost[index]);
    }
    long tmp = cal(index + 1, consecutivePairs + (1 - cur == lastChar ? 1 : 0), 1 - cur, S, cost);
    if (tmp != Long.MAX_VALUE) {
        tmp += (cur == lastChar ? cost[index] : 0);
    }
    res = Long.min(res, tmp);
    return dp[index][consecutivePairs][lastChar] = res;
}
